package android.graphics;import java.util.ArrayList;import java.util.List;import dev.mixer.android.OwnerHostProbe;public class Path {public enum FillType {WINDING,EVEN_ODD}public record Command(String operation,float[] points){}public final List<Command> commands=new ArrayList<>();public FillType fillType=FillType.WINDING;public Path(){OwnerHostProbe.hit("Path.<init>");OwnerHostProbe.hit("Path.<init>","beforeReturn");}public void setFillType(FillType type){OwnerHostProbe.hit("Path.setFillType");fillType=type;OwnerHostProbe.hit("Path.setFillType","beforeReturn");}private void add(String operation,float...points){OwnerHostProbe.hit("Path."+operation);commands.add(new Command(operation,points));OwnerHostProbe.hit("Path."+operation,"beforeReturn");}public void moveTo(float x,float y){add("moveTo",x,y);}public void lineTo(float x,float y){add("lineTo",x,y);}public void cubicTo(float x1,float y1,float x2,float y2,float x3,float y3){add("cubicTo",x1,y1,x2,y2,x3,y3);}public void close(){add("close");}}
